140	export async function usingLocalBucket<T>(
141		persistTo: string | undefined,
142		config: Config,
143		bucketName: string,
144		closure: (
145			namespace: ReplaceWorkersTypes<R2Bucket>,
146			mf: Miniflare
147		) => Promise<T>
148	): Promise<T> {
149		const persist = getLocalPersistencePath(persistTo, config);
150		const defaultPersistRoot = getDefaultPersistRoot(persist);
151		const mf = new Miniflare({
152			modules: true,
153			// TODO(soon): import `reduceError()` from `miniflare:shared`
154			script: `
155	    function reduceError(e) {
156	      return {
157	        name: e?.name,
158	        message: e?.message ?? String(e),
159	        stack: e?.stack,
160	        cause: e?.cause === undefined ? undefined : reduceError(e.cause),
161	      };
162	    }
163	    export default {
164	      async fetch(request, env, ctx) {
165	        try {
166	          if (request.method !== "PUT") return new Response(null, { status: 405 });
167	          const url = new URL(request.url);
168	          const key = url.pathname.substring(1);
169	          const optsHeader = request.headers.get("Wrangler-R2-Put-Options");
170	          const opts = JSON.parse(optsHeader);
171	          await env.BUCKET.put(key, request.body, opts);
172	          return new Response(null, { status: 204 });
173	        } catch (e) {
174	          const error = reduceError(e);
175	          return Response.json(error, {
176	            status: 500,
177	            headers: { "MF-Experimental-Error-Stack": "true" },
178	          });
179	        }
180	      }
181	    }`,
182			defaultPersistRoot,
183			r2Buckets: { BUCKET: bucketName },
184		});
185		const bucket = await mf.getR2Bucket("BUCKET");
186		try {
187			return await closure(bucket, mf);
188		} finally {
189			await mf.dispose();
190		}
191	}
