139	/**
140	 * Make a fetch request for a specific "page" of values using a cursor.
141	 * This will make multiple requests sequentially to find the cursor for the desired page.
142	 */
143	export async function fetchCursorPage<ResponseType>(
144		complianceConfig: ComplianceConfig,
145		resource: string,
146		init: RequestInit = {},
147		queryParams?: URLSearchParams
148	): Promise<ResponseType> {
149		let cursor: string | undefined;
150		let results: ResponseType = [] as ResponseType;
151	
152		const page = parseInt(queryParams?.get("page") ?? "1", 10);
153		// Remove 'page' to then use cursor
154		queryParams?.delete("page");
155	
156		for (let currentPage = 1; currentPage <= page; currentPage++) {
157			const pageQueryParams = new URLSearchParams(queryParams);
158			if (cursor) {
159				pageQueryParams.set("cursor", cursor);
160			}
161	
162			const { response: json, status } = await fetchInternal<
163				FetchResult<ResponseType>
164			>(complianceConfig, resource, init, pageQueryParams);
165	
166			if (json.success) {
167				if (currentPage === page) {
168					results = json.result;
169				}
170	
171				if (hasCursor(json.result_info)) {
172					cursor = json.result_info.cursor;
173				} else {
174					// Requested page is out of bounds
175					if (currentPage < page) {
176						return [] as ResponseType;
177					}
178					break;
179				}
180			} else {
181				throwFetchError(resource, json, status);
182			}
183		}
184	
185		return results;
186	}
