188	interface PageResultInfo {
189		page: number;
190		per_page: number;
191		count: number;
192		total_count: number;
193	}
194	
195	export function hasMorePages(
196		result_info: unknown
197	): result_info is PageResultInfo {
198		const page = (result_info as PageResultInfo | undefined)?.page;
199		const per_page = (result_info as PageResultInfo | undefined)?.per_page;
200		const total = (result_info as PageResultInfo | undefined)?.total_count;
201	
202		return (
203			page !== undefined &&
204			per_page !== undefined &&
205			total !== undefined &&
206			page * per_page < total
207		);
208	}
