import { confirm } from "../../dialogs";
import { logger } from "../../logger";

/**
 * Header sent on R2 write requests to ask the API to reject the operation
 * (with {@link R2_DATA_CATALOG_CONFLICT_CODE}) when the target bucket has the
 * data catalog enabled, so the CLI can warn the user before proceeding.
 */
export const R2_DATA_CATALOG_CHECK_HEADER = "cf-r2-data-catalog-check";

/**
 * API error code returned (alongside HTTP 409) when a write is rejected because
 * the bucket has the data catalog enabled and the check header was sent.
 */
export const R2_DATA_CATALOG_CONFLICT_CODE = 10081;

/**
 * Prompt shown when a single write operation is rejected because the bucket has
 * the data catalog enabled.
 */
export const DATA_CATALOG_CONFLICT_PROMPT =
	"Data catalog is enabled for this bucket. Proceeding may leave the data catalog in an invalid state. Continue?";

/**
 * Upfront prompt shown before a bulk upload, since bulk uploads can't perform a
 * per-object data catalog check.
 */
export const BULK_PUT_DATA_CATALOG_PROMPT =
	"Bulk upload may overwrite existing objects. If this bucket has data catalog enabled, this operation could leave the catalog in an invalid state. Continue?";

/**
 * Whether the given error is a data catalog conflict (HTTP 409 with error code
 * {@link R2_DATA_CATALOG_CONFLICT_CODE}).
 */
export function isDataCatalogConflict(error: unknown): boolean {
	return error instanceof APIError && error.code === R2_DATA_CATALOG_CONFLICT_CODE;
}

/**
 * Runs a write operation guarded by an R2 data catalog safety check.
 *
 * When `force` is false, the operation is first attempted with the
 * `cf-r2-data-catalog-check` header set (signalled by `runOperation(true)`). If
 * the API rejects it with a data catalog conflict, the user is prompted; on
 * confirmation the operation is retried without the header.
 *
 * When `force` is true, the operation runs once without the header and no
 * confirmation is performed.
 *
 * @returns `true` if the operation completed, `false` if the user cancelled.
 */
export async function runWithDataCatalogCheck(
	force: boolean,
	runOperation: (dataCatalogCheck: boolean) => Promise<void>
): Promise<boolean> {
	if (force) {
		await runOperation(false);
		return true;
	}

	try {
		await runOperation(true);
		return true;
	} catch (error) {
		if (!isDataCatalogConflict(error)) {
			throw error;
		}

		const confirmed = await confirm(DATA_CATALOG_CONFLICT_PROMPT);
		if (!confirmed) {
			logger.log("Operation cancelled.");
			return false;
		}

		await runOperation(false);
		return true;
	}
}
