}

const putHeaderKeys = [
	"cache-control",
	"content-disposition",
	"content-encoding",
	"content-language",
	"content-length",
	"content-type",
	"expires",
] as const;

/**
 * Uploads an object to remote R2
 */
export async function putRemoteObject(
	complianceConfig: ComplianceConfig,
	accountId: string,
	bucketName: string,
	objectName: string,
	object: Readable | ReadableStream | Buffer,
	options: Record<(typeof putHeaderKeys)[number], string | undefined>,
	jurisdiction?: string,
	storageClass?: string,
	dataCatalogCheck?: boolean
): Promise<void> {
	const headers: HeadersInit = {};
	for (const key of putHeaderKeys) {
		const value = options[key] || "";
		if (value && typeof value === "string") {
			headers[key] = value;
		}
	}
	if (jurisdiction !== undefined) {
		headers["cf-r2-jurisdiction"] = jurisdiction;
	}

	if (storageClass !== undefined) {
		headers["cf-r2-storage-class"] = storageClass;
	}

	if (dataCatalogCheck) {
		headers[R2_DATA_CATALOG_CHECK_HEADER] = "true";
	}

	const result = await fetchR2Objects(
		complianceConfig,
		`/accounts/${accountId}/r2/buckets/${bucketName}/objects/${objectName}`,
		{
			body: object,
			headers,
			method: "PUT",
			duplex: "half",
		}
	);
	if (result === null) {
		throw new UserError("The specified bucket does not exist.");
	}
}
